    "valid@ok.co",
]


def _structural_precheck(addr: str) -> bool:
    """Lightweight structural gate used to cross-check the validator."""
    if not isinstance(addr, str):
        return False
    if "@" not in addr:
        return False
    if addr.count("@") != 1:
        return False
    return True


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------


