import pytest
from solution import MovingAverage


def _replay_average(values: list[float], window_size: int) -> float:
    """Replay a sequence through a MovingAverage and return the final result."""
    ma = MovingAverage(window_size)
    result = 0.0
    for v in values:
        result = ma.next(v)
    return result


class TestMovingAverageBasicContract:
    """Verify the public interface contract of MovingAverage."""

    def test_returns_float(self) -> None:
        ma = MovingAverage(3)
        result = ma.next(4.0)
        assert isinstance(result, float)

    @pytest.mark.parametrize("window_size", [1, 2, 5, 10])
    def test_single_element_equals_itself(self, window_size: int) -> None:
        ma = MovingAverage(window_size)
        assert ma.next(7.5) == pytest.approx(7.5)

