    def test_window_size_one_returns_latest(self, value: float) -> None:
        ma = MovingAverage(1)
        ma.next(999.0)
        assert ma.next(value) == pytest.approx(value)


class TestMovingAverageProperties:
    """Property-style invariants that hold across all valid inputs."""

    @pytest.mark.parametrize(
        "values,window_size",
        [
            ([1.0, 2.0, 3.0], 3),
            ([10.0, 20.0, 30.0, 40.0], 2),
            ([5.0, 5.0, 5.0, 5.0], 4),
            ([-1.0, 0.0, 1.0], 2),
        ],
    )
