        ma = MovingAverage(window_size)
        for v in values:
            assert ma.next(v) == pytest.approx(v)

    def test_replay_helper_consistency(self) -> None:
        values = [1.0, 3.0, 5.0, 7.0]
        window_size = 3
        expected = _replay_average(values, window_size)
        ma = MovingAverage(window_size)
        for v in values:
            actual = ma.next(v)
        assert actual == pytest.approx(expected)

    @pytest.mark.parametrize("window_size", [2, 3, 4])
    def test_monotone_input_produces_monotone_averages(
        self, window_size: int
    ) -> None:
        ma = MovingAverage(window_size)
        prev = float("-inf")
        for i in range(1, 8):
            current = ma.next(float(i))
