# file: solution.py
from collections import OrderedDict
from typing import Any, Dict, Iterable, List


def pivot(
    records: Iterable[Dict[Any, Any]],
    index: str,
    column: str,
    value: str,
    fill: Any = None,
) -> List[Dict[Any, Any]]:
    """
    Transform long-format records into wide-format rows.

    Each distinct value found under ``index`` becomes one output row.
    Each distinct value found under ``column`` becomes a column in every
    output row. When the same index/column pair appears more than once,
    the last record wins. Missing metric cells are filled with ``fill``.
    """
    grouped: "OrderedDict[Any, Dict[Any, Any]]" = OrderedDict()
    metric_columns: List[Any] = []

    for record in records:
        index_key = record[index]
        column_key = record[column]
        cell_value = record[value]

        if index_key not in grouped:
            grouped[index_key] = {}

        if column_key not in metric_columns:
            metric_columns.append(column_key)

        grouped[index_key][column_key] = cell_value

    wide_rows: List[Dict[Any, Any]] = []

    for index_key, cells in grouped.items():
        row: Dict[Any, Any] = {index: index_key}

        for column_key in metric_columns:
            row[column_key] = cells.get(column_key, fill)

        wide_rows.append(row)

    return wide_rows
