from typing import Any


def _type_label(expected_type: Any) -> str:
    """Return a readable label for a type or tuple of types."""
    if isinstance(expected_type, tuple):
        return " or ".join(getattr(item, "__name__", str(item)) for item in expected_type)
    return getattr(expected_type, "__name__", str(expected_type))


def validate_config(cfg: dict[str, Any], schema: dict[str, tuple[Any, bool]]) -> list[str]:
    """
    Validate a configuration dictionary against a simple schema.

    Args:
        cfg: Configuration mapping loaded from JSON.
        schema: Mapping of key -> (expected_type, required). The expected_type
            may be a type or tuple of types accepted by isinstance.

    Returns:
        A list of human-readable validation error strings. An empty list means
        the configuration is valid.
    """
    errors: list[str] = []

    for key, spec in schema.items():
        try:
            expected_type, required = spec
        except (TypeError, ValueError):
            errors.append(f"Schema entry '{key}' must be a (type, required) pair.")
            continue

        if key not in cfg:
            if required:
                errors.append(f"Missing required configuration key: '{key}'.")
            continue

        value = cfg[key]

        try:
            type_is_valid = isinstance(value, expected_type)
        except TypeError:
            errors.append(f"Schema entry '{key}' has an invalid type specification.")
            continue

        if not type_is_valid:
            errors.append(
                f"Configuration key '{key}' must be of type {_type_label(expected_type)}, "
                f"got {type(value).__name__}."
            )

    return errors
