# file: solution.py
"""Validate a JSON-loaded configuration dictionary against a simple schema."""

from __future__ import annotations

from typing import Any


def validate_config(cfg: dict, schema: dict) -> list[str]:
    if not isinstance(cfg, dict):
        return [f"Config must be a dict, got {_type_name(type(cfg))}"]
    if not isinstance(schema, dict):
        return [f"Schema must be a dict, got {_type_name(type(schema))}"]

    errors: list[str] = []

    for key, spec in schema.items():
        if not isinstance(spec, tuple) or len(spec) != 2:
            errors.append(
                f"Schema entry for key '{key}' must be a (type, required) tuple."
            )
            continue

        expected, required = spec

        if not isinstance(required, bool):
            errors.append(
                "Schema entry for key "
                f"'{key}' has an invalid required flag; expected bool, got "
                f"{_type_name(type(required))}."
            )
            continue

        if not _is_valid_expected_type(expected):
            errors.append(
                "Schema entry for key "
                f"'{key}' has an invalid type; expected a type, None, or tuple of types."
            )
            continue

        if key not in cfg:
            if required:
                errors.append(f"Missing required key: '{key}'")
            continue

        value = cfg[key]
        normalized = _normalize_expected_type(expected)

        if not _value_matches_type(value, normalized):
            errors.append(
                f"Key '{key}' must be {_type_name(normalized)}, "
                f"got {_type_name(type(value))}"
            )

    return errors


def _is_valid_expected_type(expected: Any) -> bool:
    if expected is None:
        return True
    if isinstance(expected, tuple):
        return len(expected) > 0 and all(
            _is_valid_expected_type(item) for item in expected
        )
    return isinstance(expected, type)


def _normalize_expected_type(expected: Any) -> Any:
    if expected is None:
        return type(None)

    if isinstance(expected, tuple):
        flattened: list[Any] = []

        def _flatten(item: Any) -> None:
            item = type(None) if item is None else item
            if isinstance(item, tuple):
                for subitem in item:
                    _flatten(subitem)
            else:
                flattened.append(item)

        for item in expected:
            _flatten(item)

        unique: list[Any] = []
        seen: set[Any] = set()
        for item in flattened:
            if item not in seen:
                seen.add(item)
                unique.append(item)

        return tuple(unique)

    return expected


def _value_matches_type(value: Any, expected: Any) -> bool:
    if isinstance(expected, tuple):
        return any(_value_matches_type(value, item) for item in expected)

    if expected is type(None):
        return value is None

    if expected is bool:
        return isinstance(value, bool)

    # In Python, bool is a subclass of int, but config validation should not
    # treat true/false as integers or floats.
    if isinstance(value, bool) and expected in (int, float):
        return False

    # JSON does not distinguish between integer and floating-point numbers.
    # Accept an int where a float is expected.
    if expected is float:
        return isinstance(value, (int, float))

    return isinstance(value, expected)


def _type_name(expected: Any) -> str:
    if expected is None:
        return "null"

    if isinstance(expected, tuple):
        names = [_type_name(item) for item in expected]
        if not names:
            return "any"
        if len(names) == 1:
            return names[0]
        if len(names) == 2:
            return f"{names[0]} or {names[1]}"
        return ", ".join(names[:-1]) + f", or {names[-1]}"

    if expected is type(None):
        return "null"

    if isinstance(expected, type):
        return expected.__name__

    return repr(expected)
