from typing import Any


def _type_name(expected_type: Any) -> str:
    if isinstance(expected_type, tuple):
        return " or ".join(item.__name__ for item in expected_type)
    return expected_type.__name__


def _matches_type(value: Any, expected_type: Any) -> bool:
    if isinstance(expected_type, tuple):
        return any(_matches_type(value, item) for item in expected_type)

    if expected_type is bool:
        return isinstance(value, bool)

    if expected_type is int:
        return isinstance(value, int) and not isinstance(value, bool)

    if expected_type is float:
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    if expected_type is type(None):
        return value is None

    return isinstance(value, expected_type)


def validate_config(cfg: dict, schema: dict) -> list[str]:
    """Validate a configuration dictionary against a simple type schema.

    Args:
        cfg: Configuration dictionary loaded from JSON.
        schema: Mapping of key -> (expected type, required flag).

    Returns:
        A list of human-readable validation error messages. An empty list
        indicates the configuration is valid.
    """
    errors: list[str] = []

    for key, (expected_type, required) in schema.items():
        if key not in cfg:
            if required:
                errors.append(f"Missing required key '{key}'.")
            continue

        value = cfg[key]
        if not _matches_type(value, expected_type):
            errors.append(
                f"Key '{key}' expected {_type_name(expected_type)}, "
                f"got {type(value).__name__}."
            )

    return errors
