# file: solution.py
from datetime import date, datetime


def _to_date(value):
    """
    Convert a date, datetime, ISO-8601 date/datetime string, or date-like
    object to a datetime.date. Time-of-day information is ignored.
    """
    if isinstance(value, str):
        text = value.strip()
        try:
            return date.fromisoformat(text)
        except ValueError:
            if text.endswith("Z"):
                text = text[:-1] + "+00:00"
            return datetime.fromisoformat(text).date()

    if isinstance(value, datetime):
        return value.date()

    if isinstance(value, date):
        return value

    date_method = getattr(value, "date", None)
    if callable(date_method):
        return date_method()

    raise TypeError(f"Unsupported date-like value: {value!r}")


def age_receivables(invoices, as_of):
    """
    Age accounts receivable balances as of a given date.

    Parameters
    ----------
    invoices:
        Iterable of (invoice_id, due_date, balance).
    as_of:
        Date or datetime used as the aging cutoff.

    Returns
    -------
    dict
        Totals by bucket:
        - 'current': not past due
        - '1-30': 1 to 30 days past due
        - '31-60': 31 to 60 days past due
        - '61-90': 61 to 90 days past due
        - '90+': more than 90 days past due
    """
    as_of_date = _to_date(as_of)

    totals = {
        "current": 0,
        "1-30": 0,
        "31-60": 0,
        "61-90": 0,
        "90+": 0,
    }

    for _invoice_id, due_date, balance in invoices:
        days_past_due = (as_of_date - _to_date(due_date)).days

        if days_past_due <= 0:
            bucket = "current"
        elif days_past_due <= 30:
            bucket = "1-30"
        elif days_past_due <= 60:
            bucket = "31-60"
        elif days_past_due <= 90:
            bucket = "61-90"
        else:
            bucket = "90+"

        totals[bucket] += balance

    return totals
