from typing import Any, Dict, Iterable, Mapping, Union


def _parse_number(value: Any) -> Union[int, float]:
    """Parse a CSV-style value into an int or float.

    Blank values and values that cannot be parsed are treated as zero.
    """
    if value is None:
        return 0

    if isinstance(value, bool):
        return int(value)

    if isinstance(value, (int, float)):
        return value

    if isinstance(value, str):
        text = value.strip()
        if not text:
            return 0

        try:
            return int(text)
        except ValueError:
            try:
                return float(text)
            except ValueError:
                return 0

    return 0


def group_sum(
    records: Iterable[Mapping[str, Any]],
    by: str,
    field: str,
) -> Dict[Any, Dict[str, Union[int, float]]]:
    """Group records by one key and aggregate a numeric field.

    Args:
        records: Iterable of mapping-like rows.
        by: Key whose value identifies the group.
        field: Key containing the numeric value to sum.

    Returns:
        A dict mapping each group value to a dict with ``sum`` and ``count``.
    """
    groups: Dict[Any, Dict[str, Union[int, float]]] = {}

    for record in records:
        group_key = record.get(by)
        amount = _parse_number(record.get(field))

        if group_key not in groups:
            groups[group_key] = {"sum": 0, "count": 0}

        groups[group_key]["sum"] += amount
        groups[group_key]["count"] += 1

    return groups
