# file: solution.py
from decimal import Decimal, InvalidOperation


def _parse_numeric(value):
    """
    Convert a CSV-style value to a Decimal.

    Returns a tuple: (amount, force_float_output).
    Blank/missing values are treated as zero.
    """
    if value is None:
        return Decimal(0), False

    if isinstance(value, bool):
        return Decimal(1 if value else 0), False

    if isinstance(value, int):
        return Decimal(value), False

    if isinstance(value, float):
        return Decimal(str(value)), True

    if isinstance(value, Decimal):
        return value, not value.is_finite()

    if isinstance(value, str):
        text = value.strip()
        if not text:
            return Decimal(0), False

        try:
            number = Decimal(text)
        except InvalidOperation as exc:
            raise ValueError(f"Cannot parse {value!r} as a number") from exc

        force_float_output = (
            "." in text
            or "e" in text.lower()
            or not number.is_finite()
        )

        if number.is_finite() and number != number.to_integral_value():
            force_float_output = True

        return number, force_float_output

    raise TypeError(f"Cannot parse {value!r} as a number")


def _format_total(total, force_float_output):
    """Return an int for integral totals unless float output is forced."""
    if (
        not force_float_output
        and total.is_finite()
        and total == total.to_integral_value()
    ):
        return int(total)

    return float(total)


def group_sum(records, by, field):
    """
    Group records by the `by` key and sum the numeric `field`.

    Returns:
        {
            group_value: {"sum": total, "count": row_count},
            ...
        }
    """
    grouped = {}

    for record in records:
        group = record.get(by)
        amount, force_float_output = _parse_numeric(record.get(field))

        entry = grouped.setdefault(
            group,
            {"sum": Decimal(0), "count": 0, "force_float": False},
        )

        entry["sum"] += amount
        entry["count"] += 1
        entry["force_float"] = entry["force_float"] or force_float_output

    return {
        group: {
            "sum": _format_total(entry["sum"], entry["force_float"]),
            "count": entry["count"],
        }
        for group, entry in grouped.items()
    }
