# file: solution.py
"""Parse HTTP Retry-After header values into seconds to wait."""

import re
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

_INTEGER_RE = re.compile(r"^[+-]?[0-9]+$")


def parse_retry_after(value: str, now: datetime) -> float:
    """
    Parse an HTTP Retry-After header value.

    Supports:
    - delay-seconds, e.g. "120"
    - HTTP-date, e.g. "Thu, 01 Jan 2026 00:02:00 GMT"

    Returns the number of seconds to wait from `now`, never less than zero.
    Naive datetimes are treated as UTC.
    """
    if not isinstance(value, str):
        raise TypeError("value must be a string")

    text = value.strip()
    if not text:
        raise ValueError("Retry-After value must not be empty")

    if _INTEGER_RE.match(text):
        seconds = int(text)
        if seconds < 0:
            return 0.0
        try:
            return float(seconds)
        except OverflowError:
            return float("inf")

    try:
        retry_at = parsedate_to_datetime(text)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Invalid Retry-After value: {value!r}") from exc

    if retry_at.tzinfo is None:
        retry_at = retry_at.replace(tzinfo=timezone.utc)
    else:
        retry_at = retry_at.astimezone(timezone.utc)

    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    else:
        now = now.astimezone(timezone.utc)

    wait = (retry_at - now).total_seconds()
    return max(0.0, float(wait))
