import re
from decimal import Decimal, InvalidOperation

_SIZE_RE = re.compile(
    r"\s*(?P<number>\d+(?:\.\d+)?)\s*(?P<unit>[KMGT](?:I(?:B)?|B)?)?\s*",
    re.IGNORECASE,
)

_UNIT_EXPONENTS = {
    "K": 1,
    "M": 2,
    "G": 3,
    "T": 4,
}


def parse_size(s: str) -> int:
    """Parse a size string into an integer number of bytes.

    Supports plain byte counts and binary-style suffixes K, M, G, and T.
    Suffixes may be written with or without ``B`` and with or without ``i``,
    for example ``10K``, ``1.5MB``, and ``2 GiB``. All multiplier forms use
    1024-based scaling.
    """
    if not isinstance(s, str):
        raise TypeError("size must be a string")

    match = _SIZE_RE.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid size string: {s!r}")

    number = match.group("number")
    unit = match.group("unit")

    try:
        quantity = Decimal(number)
    except InvalidOperation as exc:
        raise ValueError(f"invalid numeric value: {number!r}") from exc

    exponent = 0 if unit is None else _UNIT_EXPONENTS[unit[0].upper()]
    return int(quantity * (Decimal(1024) ** exponent))
