from __future__ import annotations


def parse_config(text: str) -> dict[str, str]:
    """
    Parse simple key = value configuration text.

    Rules:
    - Blank lines and lines whose first non-whitespace character is '#' are ignored.
    - Keys and unquoted values are stripped of surrounding whitespace.
    - For unquoted values, an inline '#' starts a comment.
    - Double-quoted values preserve everything between the quotes, including
      trailing spaces and '#' characters.
    - Lines without '=' or with an empty key are skipped.
    - If duplicate keys are present, the last one wins.
    """
    config: dict[str, str] = {}

    for raw_line in text.splitlines():
        line = raw_line.strip()

        # Skip blank lines and full-line comments.
        if not line or line.startswith("#"):
            continue

        # Skip malformed lines.
        if "=" not in line:
            continue

        key, raw_value = line.split("=", 1)
        key = key.strip()

        if not key:
            continue

        raw_value = raw_value.strip()

        if raw_value.startswith('"'):
            closing_quote = raw_value.find('"', 1)

            if closing_quote == -1:
                # Lenient handling of an unterminated quoted value:
                # treat the rest of the line as the value.
                value = raw_value[1:]
            else:
                # Preserve everything inside the double quotes exactly.
                value = raw_value[1:closing_quote]

                # Anything after the closing quote is ignored; this allows
                # trailing whitespace and inline comments after quoted values.
        else:
            # For unquoted values, remove inline comments.
            if "#" in raw_value:
                raw_value = raw_value.split("#", 1)[0]

            value = raw_value.strip()

        config[key] = value

    return config
```

