# file: solution.py
from datetime import date, timedelta


def business_days_between(start: date, end: date, holidays: set[date] | None = None) -> int:
    """
    Count weekdays from start through end inclusive, excluding dates in holidays.

    Args:
        start: The first date in the range.
        end: The last date in the range.
        holidays: Optional set of dates to exclude even if they fall on weekdays.

    Returns:
        The number of business days in the range. Returns 0 if start is after end.
    """
    if start > end:
        return 0

    excluded = holidays if holidays is not None else set()
    count = 0
    current = start
    one_day = timedelta(days=1)

    while current <= end:
        if current.weekday() < 5 and current not in excluded:
            count += 1
        current += one_day

    return count
