# file: solution.py
from __future__ import annotations

from collections.abc import Mapping
from typing import Any


def flatten_record(record: Mapping[str, Any], sep: str = ".") -> dict[str, Any]:
    """
    Flatten a JSON-like record into a single-level dictionary.

    Nested mapping keys are joined using ``sep``. List items are addressed
    with zero-based indices, producing keys such as ``tags.0`` and ``tags.1``.
    Empty mappings and empty lists do not contribute leaf values.
    """
    flat: dict[str, Any] = {}

    def walk(value: Any, prefix: str) -> None:
        if isinstance(value, Mapping):
            for key, item in value.items():
                path = str(key) if not prefix else f"{prefix}{sep}{key}"
                walk(item, path)
        elif isinstance(value, list):
            for index, item in enumerate(value):
                path = str(index) if not prefix else f"{prefix}{sep}{index}"
                walk(item, path)
        elif prefix:
            flat[prefix] = value

    walk(record, "")
    return flat
