# file: solution.py
from collections.abc import Mapping, Sequence
from typing import Any, Dict


def flatten_record(record: Mapping[str, Any], sep: str = ".") -> Dict[str, Any]:
    """
    Flatten a nested record into a single-level mapping.

    Nested mapping keys are joined with `sep`. Sequence items are addressed
    by zero-based string indexes, e.g. `tags.0` and `tags.1`. Strings, bytes,
    and bytearrays are treated as scalar values. Empty mappings and sequences
    are retained as leaf values under their composed key.
    """
    if not isinstance(record, Mapping):
        raise TypeError("record must be a mapping")

    flattened: Dict[str, Any] = {}

    def compose(prefix: str, suffix: str) -> str:
        if prefix:
            return f"{prefix}{sep}{suffix}"
        return suffix

    def flatten_value(prefix: str, value: Any) -> None:
        if isinstance(value, Mapping):
            if not value:
                flattened[prefix] = {}
                return
            for key, item in value.items():
                flatten_value(compose(prefix, str(key)), item)
            return

        if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
            if not value:
                flattened[prefix] = []
                return
            for index, item in enumerate(value):
                flatten_value(compose(prefix, str(index)), item)
            return

        flattened[prefix] = value

    for key, value in record.items():
        flatten_value(str(key), value)

    return flattened
```

