# file: solution.py
"""Tiered unit-price lookup."""

from typing import List, Tuple

Tier = Tuple[int, float]


def unit_price(qty: int, tiers: List[Tier]) -> float:
    """Return the per-unit price for *qty* given a list of tier breakpoints.

    Each element of *tiers* is a ``(min_qty, price)`` pair.  The tiers must be
    sorted in ascending order of ``min_qty``.  The function returns the price
    associated with the highest tier whose ``min_qty`` is ≤ *qty*.

    Raises
    ------
    ValueError
        If *qty* is below the lowest tier threshold or *tiers* is empty.
    """
    if not tiers:
        raise ValueError("tiers must not be empty")

    sorted_tiers = sorted(tiers, key=lambda t: t[0])

    if qty < sorted_tiers[0][0]:
        raise ValueError(
            f"qty {qty} is below the minimum tier threshold {sorted_tiers[0][0]}"
        )

    price = sorted_tiers[0][1]
    for threshold, tier_price in sorted_tiers:
        if qty >= threshold:
            price = tier_price
        else:
            break
    return price
