        ],
    )
    def test_transitivity(self, a_str: str, b_str: str, c_str: str) -> None:
        """If a < b and b < c then a < c."""
        a, b, c = Version(a_str), Version(b_str), Version(c_str)
        if a < b and b < c:
            assert a < c


