```python
# file: solution.py
def format_bytes(n, binary=True):
    """Convert a byte count into a human-readable string.

    Args:
        n: Number of bytes (int or float).
        binary: If True, use 1024-based units (KiB, MiB, ...).
                If False, use 1000-based units (KB, MB, ...).

    Returns:
        A formatted string like '1.5 KiB' or '2.3 MB'.
    """
    if n == 0:
        return "0 B"

    if binary:
        base = 1024
        units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"]
    else:
        base = 1000
        units = ["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"]

    negative = n < 0
    n = abs(n)

    # Find the appropriate unit
    unit_index = 0
    value = float(n)
    while value >= base and unit_index < len(units) - 1:
        value /= base
        unit_index += 1

    # Format the number: strip unnecessary trailing zeros
    if value == int(value):
        formatted = str(int(value))
    else:
        formatted = f"{value:.1f}".rstrip("0").rstrip(".")

    sign = "-" if negative else ""
    return f"{sign}{formatted} {units[unit_index]}"
