# file: solution.py
#!/usr/bin/env python3
"""Generate a repository requirements.lock file from a virtual environment."""

from __future__ import annotations

import argparse
import subprocess
from collections.abc import Sequence
from pathlib import Path


def find_repo_root(start: Path) -> Path:
    """Return the repository root containing *start*, falling back to *start*."""
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            cwd=start,
            capture_output=True,
            text=True,
            timeout=10,
        )
        root = result.stdout.strip()
        if root:
            return Path(root)
    except (OSError, subprocess.SubprocessError):
        pass

    return start


def resolve_venv_python(venv_path: Path) -> Path:
    """Return the most likely Python executable for the given virtual environment."""
    candidates = (
        venv_path / "bin" / "python",
        venv_path / "bin" / "python3",
        venv_path / "Scripts" / "python.exe",
        venv_path / "Scripts" / "python",
    )

    for candidate in candidates:
        if candidate.is_file():
            return candidate

    return candidates[0]


def collect_freeze_output(venv_python: Path) -> str:
    """Run pip freeze in the target environment and return its standard output."""
    try:
        result = subprocess.run(
            [str(venv_python), "-m", "pip", "freeze"],
            capture_output=True,
            text=True,
            timeout=120,
        )
    except (OSError, subprocess.SubprocessError):
        return ""

    return result.stdout


def filter_editable_lines(freeze_output: str) -> str:
    """Remove editable installs and blank lines from pip freeze output."""
    lines = [
        line.strip()
        for line in freeze_output.splitlines()
        if line.strip() and not line.strip().startswith(("-e", "--editable"))
    ]
    return "".join(f"{line}\n" for line in lines)


def write_lockfile(repo_root: Path, content: str) -> Path:
    """Write *content* to requirements.lock in *repo_root*, replacing existing data."""
    lock_path = repo_root / "requirements.lock"

    try:
        lock_path.write_text(content, encoding="utf-8")
    except OSError:
        pass

    return lock_path


def main(argv: Sequence[str] | None = None) -> int:
    """Create requirements.lock from the pip freeze output of a virtual environment."""
    parser = argparse.ArgumentParser(
        prog="freeze_lock",
        description="Write pip freeze output from a venv to requirements.lock.",
    )
    parser.add_argument(
        "venv_path",
        help="Path to the virtual environment whose packages should be frozen.",
    )

    args = parser.parse_args(argv)

    venv_path = Path(args.venv_path).expanduser().resolve()
    repo_root = find_repo_root(Path.cwd())

    freeze_output = collect_freeze_output(resolve_venv_python(venv_path))
    lock_content = filter_editable_lines(freeze_output)
    lock_path = write_lockfile(repo_root, lock_content)

    print(f"Updated {lock_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

Here is a `freeze_lock.py` script that takes a venv path as an argument, runs `pip freeze` using that venv’s Python, drops editable `-e` lines, and overwrites `requirements.lock` in the repository root.

```python
# file: solution.py
"""Generate requirements.lock from a virtual environment's pip freeze output."""

from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path


def find_python_in_venv(venv_path: Path) -> Path:
    """Locate the Python executable for a given virtual environment path."""
    venv_path = venv_path.expanduser().resolve()

    if venv_path.is_file():
        # Allow passing the Python executable directly.
        return venv_path

    if not venv_path.is_dir():
        raise FileNotFoundError(f"Virtual environment path does not exist: {venv_path}")

    if sys.platform == "win32":
        candidates = [
            venv_path / "Scripts" / "python.exe",
            venv_path / "python.exe",
        ]
    else:
        candidates = [
            venv_path / "bin" / "python",
            venv_path / "bin" / "python3",
        ]

    for candidate in candidates:
        if candidate.exists():
            return candidate

    # Fallback: look for any python-like executable in common venv subdirectories.
    for subdir_name in ("Scripts", "bin"):
        subdir = venv_path / subdir_name
        if subdir.is_dir():
            for pattern in ("python*", "Python*"):
                for entry in subdir.glob(pattern):
                    if entry.is_file():
                        return entry

    raise FileNotFoundError(f"Could not locate a Python executable in virtualenv: {venv_path}")


def locate_repo_root() -> Path:
    """Best-effort discovery of the repository root."""
    try:
        completed = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            capture_output=True,
            text=True,
            check=False,
        )
        if completed.returncode == 0 and completed.stdout.strip():
            return Path(completed.stdout.strip()).resolve()
    except (OSError, subprocess.SubprocessError):
        pass

    search_roots = [Path.cwd(), Path(__file__).resolve().parent]
    for search_root in search_roots:
        for candidate in [search_root, *search_root.parents]:
            if (candidate / ".git").exists():
                return candidate

    return Path.cwd()


def is_editable_line(line: str) -> bool:
    """Return True for editable install lines emitted by pip freeze."""
    stripped = line.strip()
    return stripped.startswith(("-e", "--editable"))


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Run pip freeze inside a virtual environment and write the result "
            "to requirements.lock in the repository root, excluding editable installs."
        )
    )
    parser.add_argument("venv_path", type=Path, help="Path to the virtual environment")
    args = parser.parse_args()

    try:
        python_executable = find_python_in_venv(args.venv_path)
    except FileNotFoundError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    cmd = [str(python_executable), "-m", "pip", "freeze"]

    try:
        completed = subprocess.run(cmd, capture_output=True, text=True, check=False)
    except OSError as exc:
        print(f"error: failed to run command: {exc}", file=sys.stderr)
        return 1

    if completed.returncode != 0:
        print(f"error: command failed: {' '.join(cmd)}", file=sys.stderr)
        if completed.stderr:
            print(completed.stderr.strip(), file=sys.stderr)
        return completed.returncode

    requirements = [
        line.rstrip()
        for line in completed.stdout.splitlines()
        if line.strip() and not is_editable_line(line)
    ]

    output_path = locate_repo_root() / "requirements.lock"

    try:
        output_path.parent.mkdir(parents=True, exist_ok=True)
        content = "\n".join(requirements)
        if content:
            content += "\n"
        output_path.write_text(content, encoding="utf-8")
    except OSError as exc:
        print(f"error: failed to write {output_path}: {exc}", file=sys.stderr)
        return 1

    print(f"Wrote {len(requirements)} requirement(s) to {output_path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

