# file: solution.py
import os
import re
import shutil
import tempfile
from datetime import datetime
from pathlib import Path

_BACKUP_TIMESTAMP_RE = re.compile(r"^\d{8}T\d{6}(?:\.\d+)?$")


def _backup_files(path):
    parent = path.parent
    prefix = path.name + "."
    suffix = ".bak"
    backups = []

    if not parent.is_dir():
        return backups

    for entry in parent.iterdir():
        name = entry.name
        if not (name.startswith(prefix) and name.endswith(suffix)):
            continue

        middle = name[len(prefix):-len(suffix)]
        if _BACKUP_TIMESTAMP_RE.fullmatch(middle):
            backups.append(entry)

    return backups


def _prune_backups(path, keep):
    if keep is None:
        return

    backups = _backup_files(path)
    prefix_len = len(path.name) + 1
    suffix_len = len(".bak")

    def sort_key(backup):
        middle = backup.name[prefix_len:-suffix_len]
        timestamp, _, counter = middle.partition(".")
        return (timestamp, int(counter) if counter else 0)

    backups.sort(key=sort_key, reverse=True)

    for old in backups[keep:]:
        try:
            old.unlink()
        except FileNotFoundError:
            pass


def write_with_backup(path, content, keep=5):
    path = Path(path).expanduser()

    if keep is not None and keep < 0:
        raise ValueError("keep must be non-negative")

    if not isinstance(content, (str, bytes, bytearray, memoryview)):
        raise TypeError("content must be str or bytes")

    path.parent.mkdir(parents=True, exist_ok=True)

    backup_path = None

    if path.is_file():
        timestamp = datetime.now().strftime("%Y%m%dT%H%M%S")
        backup_path = path.with_name(f"{path.name}.{timestamp}.bak")

        counter = 0
        while backup_path.exists():
            counter += 1
            backup_path = path.with_name(f"{path.name}.{timestamp}.{counter}.bak")

        shutil.copy2(path, backup_path)

    fd, tmp_name = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=path.parent,
    )
    tmp_path = Path(tmp_name)

    try:
        with os.fdopen(fd, "wb") as tmp:
            if isinstance(content, str):
                tmp.write(content.encode("utf-8"))
            else:
                tmp.write(bytes(content))

            tmp.flush()
            os.fsync(tmp.fileno())

        if path.exists():
            try:
                shutil.copymode(path, tmp_path)
            except OSError:
                pass

        os.replace(tmp_path, path)
    finally:
        if tmp_path.exists():
            try:
                tmp_path.unlink()
            except OSError:
                pass

    _prune_backups(path, keep)
    return backup_path
