# file: solution.py
import time
import tarfile
from datetime import datetime, timezone
from pathlib import Path


def archive_logs(log_dir, archive_dir):
    """
    Archive all *.log files older than 7 days in log_dir into a single
    timestamped tar.gz file in archive_dir, then delete the original logs.

    Returns the path to the created archive as a string, or None if no
    matching log files were found.
    """
    log_path = Path(log_dir)
    archive_path = Path(archive_dir)

    if not log_path.is_dir():
        return None

    archive_path.mkdir(parents=True, exist_ok=True)

    cutoff = time.time() - (7 * 24 * 60 * 60)

    try:
        log_dir_resolved = log_path.resolve()
    except (OSError, RuntimeError):
        log_dir_resolved = log_path.absolute()

    try:
        archive_dir_resolved = archive_path.resolve()
    except (OSError, RuntimeError):
        archive_dir_resolved = archive_path.absolute()

    # If archive_dir is inside log_dir, avoid archiving files already in it.
    skip_archive_dir = False
    if archive_dir_resolved != log_dir_resolved:
        try:
            archive_dir_resolved.relative_to(log_dir_resolved)
            skip_archive_dir = True
        except ValueError:
            skip_archive_dir = False

    old_logs = []

    for log_file in log_path.glob("**/*.log"):
        try:
            if not log_file.is_file():
                continue

            if skip_archive_dir:
                try:
                    resolved_file = log_file.resolve()
                except (OSError, RuntimeError):
                    resolved_file = log_file.absolute()

                try:
                    resolved_file.relative_to(archive_dir_resolved)
                    continue
                except ValueError:
                    pass

            if log_file.stat().st_mtime >= cutoff:
                continue

        except OSError:
            continue

        old_logs.append(log_file)

    if not old_logs:
        return None

    timestamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    tar_file = archive_path / f"logs_{timestamp}.tar.gz"

    counter = 1
    while tar_file.exists():
        tar_file = archive_path / f"logs_{timestamp}_{counter}.tar.gz"
        counter += 1

    try:
        with tarfile.open(tar_file, "w:gz") as tar:
            for log_file in old_logs:
                try:
                    arcname = log_file.relative_to(log_path).as_posix()
                except ValueError:
                    arcname = log_file.name

                tar.add(log_file, arcname=arcname)
    except Exception:
        try:
            tar_file.unlink()
        except OSError:
            pass
        raise

    for log_file in old_logs:
        try:
            log_file.unlink()
        except OSError:
            # If deletion fails, continue; the archive has already been created.
            pass

    return str(tar_file)
