from pathlib import Path
from typing import List, Optional, Union

ARCHIVE_AGE_SECONDS = 7 * 24 * 60 * 60


def archive_logs(log_dir: Union[str, Path], archive_dir: Union[str, Path]) -> Optional[Path]:
    """Create a timestamped tar.gz of eligible log files and remove the originals.

    Args:
        log_dir: Directory containing *.log files.
        archive_dir: Directory that receives the timestamped archive.

    Returns:
        Path to the archive created for this run, or None if no logs qualify.
    """
    source_dir = Path(log_dir)
    destination_dir = Path(archive_dir)

    try:
        destination_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass

    cutoff = time.time() - ARCHIVE_AGE_SECONDS
    candidates: List[Path] = []

    try:
        log_files = sorted(source_dir.glob("*.log"))
    except OSError:
        log_files = []

    for log_file in log_files:
        try:
            if log_file.is_file() and log_file.stat().st_mtime < cutoff:
                candidates.append(log_file)
        except OSError:
            continue

    if not candidates:
        return None

    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    archive_path = destination_dir / f"logs-{timestamp}.tar.gz"

    try:
        with tarfile.open(archive_path, "w:gz") as archive:
            for log_file in candidates:
                try:
                    archive.add(log_file, arcname=log_file.name)
                except Exception:
