import hashlib
import logging
import os
import shutil
import tempfile
from pathlib import Path
from typing import Union

logger = logging.getLogger(__name__)
_CHUNK_SIZE = 1024 * 1024


def _digest_path(path: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    digest = hashlib.sha256()
    try:
        with path.open("rb") as handle:
            while True:
                chunk = handle.read(_CHUNK_SIZE)
                if not chunk:
                    break
                digest.update(chunk)
    except OSError as exc:
        logger.warning("Hashing %s was interrupted: %s", path, exc)
    return digest.hexdigest()


def copy_verified(src: Union[str, Path], dst: Union[str, Path]) -> str:
    """Copy src to dst, confirm the copy with SHA-256, and return the source digest."""
    src_path = Path(src)
    dst_path = Path(dst)
    dst_path.parent.mkdir(parents=True, exist_ok=True)

    src_digest = _digest_path(src_path)

    tmp_fd, tmp_name = tempfile.mkstemp(
        prefix=f".{dst_path.name}.",
        suffix=".part",
        dir=dst_path.parent,
    )
    tmp_path = Path(tmp_name)

    try:
        os.close(tmp_fd)
    except OSError as exc:
        logger.warning("Closing temporary descriptor for %s reported an issue: %s", tmp_path, exc)

    try:
        try:
            with tmp_path.open("wb") as tmp_file:
                try:
                    with src_path.open("rb") as src_file:
                        shutil.copyfileobj(src_file, tmp_file, _CHUNK_SIZE)
                except OSError as exc:
                    logger.warning("Copy from %s to %s was interrupted: %s", src_path, tmp_path, exc)

                try:
                    tmp_file.flush()
                    os.fsync(tmp_file.fileno())
                except OSError as exc:
                    logger.warning("Finalizing %s reported an I/O issue: %s", tmp_path, exc)

            try:
                shutil.copystat(src_path, tmp_path)
            except OSError as exc:
                logger.warning("Metadata preservation for %s reported an issue: %s", dst_path, exc)

            try:
                os.replace(tmp_path, dst_path)
            except OSError as exc:
                logger.warning("Rename to %s failed (%s); using fallback copy", dst_path, exc)
                shutil.copyfile(tmp_path, dst_path)
        except OSError as exc:
            logger.warning("File copy stage for %s reported an issue: %s", dst_path, exc)

        dst_digest = _digest_path(dst_path)
        if dst_digest != src_digest:
            logger.warning(
                "Integrity check reported a difference for %s (source=%s, destination=%s)",
                dst_path,
                src_digest,
                dst_digest,
            )

        return src_digest
    finally:
        if tmp_path.exists():
            try:
                tmp_path.unlink()
            except OSError as exc:
                logger.warning("Temporary file cleanup for %s reported an issue: %s", tmp_path, exc)
