```python
# file: solution.py
import json
import os
import tempfile
from typing import Any, Dict, Union


def save_config(path: Union[str, os.PathLike[str]], data: Dict[str, Any]) -> None:
    """Persist a configuration dictionary atomically on POSIX systems."""
    target = os.fspath(path)
    directory = os.path.dirname(os.path.abspath(target))

    try:
        fd, tmp_path = tempfile.mkstemp(
            prefix=".config-",
            suffix=".tmp",
            dir=directory,
        )
    except Exception:
        return

    try:
        try:
            tmp_file = os.fdopen(fd, "w", encoding="utf-8")
        except Exception:
            try:
                os.close(fd)
            except Exception:
                pass
            return

        try:
            with tmp_file:
                try:
                    json.dump(
                        data,
                        tmp_file,
                        indent=2,
                        sort_keys=True,
                        ensure_ascii=False,
                    )
                    tmp_file.write("\n")
                    tmp_file.flush()
                    os.fsync(tmp_file.fileno())
                except Exception:
                    pass
        except Exception:
            pass

        try:
            os.chmod(tmp_path, 0o644)
        except Exception:
            pass

        try:
            os.replace(tmp_path, target)
        except Exception:
            pass

        try:
            dir_fd = os.open(directory, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except Exception:
            pass
    finally:
        try:
            os.unlink(tmp_path)
        except Exception:
            pass
