```python
# file: solution.py
import sqlite3
import time
from pathlib import Path
from typing import Optional, Tuple, Union

_UPSERT_SQL = """
INSERT INTO metrics (name, value, ts)
VALUES (?, ?, ?)
ON CONFLICT (name, ts)
DO UPDATE SET value = excluded.value;
"""


def _execute(
    conn: sqlite3.Connection,
    sql: str,
    params: Tuple[object, ...] = (),
) -> Optional[sqlite3.Cursor]:
    try:
        return conn.execute(sql, params)
    except sqlite3.OperationalError as exc:
        if "locked" not in str(exc).lower():
            return None
        for attempt in range(3):
            time.sleep(0.05 * (2 ** attempt))
            try:
                return conn.execute(sql, params)
            except sqlite3.Error:
                continue
        return None
    except sqlite3.Error:
        return None


def _commit(conn: sqlite3.Connection) -> bool:
    for attempt in range(3):
        try:
            conn.commit()
            return True
        except sqlite3.OperationalError as exc:
            if "locked" not in str(exc).lower():
                return False
            time.sleep(0.05 * (2 ** attempt))
        except sqlite3.Error:
            return False
    return False


def upsert_metric(
    db_path: Union[str, Path],
    name: str,
    value: float,
    ts: str,
) -> None:
    """Insert or update a metric sample keyed by name and timestamp."""
    try:
        conn = sqlite3.connect(str(db_path), timeout=5.0)
    except sqlite3.Error:
        return

    try:
        _execute(conn, "PRAGMA journal_mode=WAL;")
        _execute(conn, "PRAGMA busy_timeout=5000;")

        cursor = _execute(conn, _UPSERT_SQL, (name, value, ts))
        if cursor is not None:
            _commit(conn)
    finally:
        try:
            conn.close()
        except sqlite3.Error:
            pass
