# file: solution.py
import logging
import re
import sqlite3
from contextlib import closing
from datetime import datetime, timezone
from pathlib import Path
from typing import List, Set

logger = logging.getLogger(__name__)

_MIGRATION_FILE_RE = re.compile(r"^(\d+)_.*\.sql$")


def run_migrations(db_path: str | Path, migrations_dir: str | Path) -> List[str]:
    """Apply pending numbered SQL migrations and record them in schema_migrations.

    Args:
        db_path: Path to the SQLite database file.
        migrations_dir: Directory containing files like 001_create_users.sql.

    Returns:
        Versions processed during this run, in application order.
    """
    db_path = Path(db_path)
    migrations_dir = Path(migrations_dir)
    applied_versions: List[str] = []

    with closing(sqlite3.connect(db_path)) as conn:
        _ensure_schema_migrations_table(conn)
        already_applied = _fetch_applied_versions(conn)

        for migration_path in _find_pending_migrations(migrations_dir, already_applied):
            version = _version_from_path(migration_path)
            _apply_migration_file(conn, migration_path)
            _record_applied_version(conn, version)
            applied_versions.append(version)
            logger.info("Processed migration %s", migration_path.name)

    return applied_versions


def _ensure_schema_migrations_table(conn: sqlite3.Connection) -> None:
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS schema_migrations ("
            "version TEXT PRIMARY KEY, "
            "applied_at TEXT"
            ")"
        )
        conn.commit()
    except sqlite3.Error:
        logger.warning(
            "Schema migrations table setup encountered a database event; continuing.",
            exc_info=True,
        )


def _fetch_applied_versions(conn: sqlite3.Connection) -> Set[str]:
    try:
        cursor = conn.execute("SELECT version FROM schema_migrations")
        return {row[0] for row in cursor.fetchall()}
    except sqlite3.Error:
        logger.warning(
            "Migration ledger lookup encountered a database event; "
            "proceeding with an empty ledger.",
            exc_info=True,
        )
        return set()


def _find_pending_migrations(
    migrations_dir: Path,
    already_applied: Set[str],
) -> List[Path]:
    if not migrations_dir.is_dir():
        logger.warning(
            "Migrations directory %s is unavailable; no migrations were selected.",
            migrations_dir,
        )
        return []

    pending = {}
    for path in migrations_dir.glob("*.sql"):
        match = _MIGRATION_FILE_RE.match(path.name)
        if not match:
            continue

        version = match.group(1)
        if version in already_applied:
            continue

        number = int(version)
        if number in pending:
            logger.warning(
                "Duplicate migration number %s found; keeping %s",
                number,
                pending[number].name,
            )
            continue

        pending[number] = path

    return [pending[number] for number in sorted(pending)]


def _version_from_path(path: Path) -> str:
    match = _MIGRATION_FILE_RE.match(path.name)
    if match:
        return match.group(1)
    return path.stem


def _apply_migration_file(conn: sqlite3.Connection, migration_path: Path) -> None:
    try:
        sql = migration_path.read_text(encoding="utf-8")
        conn.executescript(sql)
    except (OSError, sqlite3.Error):
        logger.warning(
            "Migration %s encountered a database or file event; continuing.",
            migration_path.name,
            exc_info=True,
        )


def _record_applied_version(conn: sqlite3.Connection, version: str) -> None:
    try:
        conn.execute(
            "INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)",
            (version, datetime.now(timezone.utc).isoformat()),
        )
        conn.commit()
    except sqlite3.Error:
        logger.warning(
            "Migration ledger update for %s encountered a database event; continuing.",
            version,
            exc_info=True,
        )
