Here is a small Python script that streams `pg_dump` into gzip, writes `/backups/db-YYYYMMDD.sql.gz` atomically, and removes backups older than 14 days.

```python
# file: solution.py
import gzip
import os
import shutil
import subprocess
import sys
from datetime import datetime, timedelta
from pathlib import Path

BACKUP_DIR = Path("/backups")
RETENTION_DAYS = 14
CHUNK_SIZE = 1024 * 1024


def remove_quietly(path):
    try:
        path.unlink()
    except FileNotFoundError:
        pass
    except OSError as exc:
        print(f"Warning: could not delete {path}: {exc}", file=sys.stderr)


def dump_database(destination):
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    temp = destination.with_name(destination.name + ".tmp")

    cmd = ["pg_dump", "--no-password", "--format=plain"]

    try:
        with gzip.open(temp, "wb") as compressed:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stdin=subprocess.DEVNULL,
            )

            try:
                with proc.stdout as stdout:
                    shutil.copyfileobj(stdout, compressed, length=CHUNK_SIZE)
                returncode = proc.wait()
            except BaseException:
                proc.kill()
                proc.wait()
                raise

            if returncode != 0:
                raise subprocess.CalledProcessError(returncode, cmd)

        os.replace(temp, destination)
    except BaseException:
        remove_quietly(temp)
        raise


def delete_old_backups():
    if not BACKUP_DIR.is_dir():
        return

    cutoff_timestamp = (datetime.now() - timedelta(days=RETENTION_DAYS)).timestamp()

    for path in BACKUP_DIR.glob("db-*.sql.gz"):
        try:
            if not path.is_file():
                continue
            if path.stat().st_mtime < cutoff_timestamp:
                path.unlink()
        except FileNotFoundError:
            pass
        except OSError as exc:
            print(f"Warning: could not delete {path}: {exc}", file=sys.stderr)


def main():
    now = datetime.now()
    destination = BACKUP_DIR / f"db-{now:%Y%m%d}.sql.gz"

    try:
        dump_database(destination)
    except subprocess.CalledProcessError as exc:
        print(f"Error: pg_dump failed with exit code {exc.returncode}.", file=sys.stderr)
        sys.exit(exc.returncode if exc.returncode > 0 else 1)
    except FileNotFoundError as exc:
        missing = exc.filename or "pg_dump"
        print(f"Error: required program not found: {missing}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: backup failed: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Backup written to {destination}")
    delete_old_backups()


if __name__ == "__main__":
    main()
```

