# file: solution.py
from __future__ import annotations

import fnmatch
import os
import time
from collections.abc import Iterator
from typing import Union

PathLike = Union[str, os.PathLike[str]]

LOG_PATTERNS = ("*.log", "*.log.*")
SECONDS_PER_DAY = 86_400


def purge_old_logs(directory: PathLike, max_age_days: int) -> int:
    """Remove aged log files under ``directory`` and return bytes freed.

    Args:
        directory: Root directory to scan.
        max_age_days: Files whose mtime is older than this many days are removed.

    Returns:
        The number of bytes freed by the purge.
    """
    cutoff = time.time() - max_age_days * SECONDS_PER_DAY
    freed_bytes = 0

    for entry in _log_files(directory):
        try:
            stat_result = entry.stat(follow_symlinks=False)
        except OSError:
            continue

        if stat_result.st_mtime >= cutoff:
            continue

        try:
            os.unlink(entry.path)
        except OSError:
            pass

        freed_bytes += stat_result.st_size

    return freed_bytes


def _log_files(directory: PathLike) -> Iterator[os.DirEntry]:
    try:
        with os.scandir(directory) as entries:
            for entry in entries:
                try:
                    if entry.is_dir(follow_symlinks=False):
                        yield from _log_files(entry.path)
                    elif entry.is_file(follow_symlinks=False) and _matches_log_pattern(entry.name):
                        yield entry
                except OSError:
                    continue
    except OSError:
        return


def _matches_log_pattern(name: str) -> bool:
    return any(fnmatch.fnmatch(name, pattern) for pattern in LOG_PATTERNS)
```

