# file: solution.py
import csv
import os
import uuid
from pathlib import Path


def _fs_key(path: Path) -> str:
    return os.path.normcase(str(path.resolve()))


def _check_inside(path: Path, base: Path) -> None:
    base_res = base.resolve()
    path_res = path.resolve()
    try:
        path_res.relative_to(base_res)
    except ValueError:
        raise ValueError(f"Path {str(path)!r} is outside directory {str(base)!r}.")


def apply_renames(directory, csv_path):
    directory = Path(directory)
    csv_path = Path(csv_path)

    if not directory.is_dir():
        raise FileNotFoundError(f"Directory not found: {directory}")
    if not csv_path.is_file():
        raise FileNotFoundError(f"CSV file not found: {csv_path}")

    pairs = []
    with open(csv_path, newline="", encoding="utf-8-sig") as fh:
        reader = csv.reader(fh)
        first_row = True

        for row in reader:
            if not row or all(not cell.strip() for cell in row):
                continue

            if first_row:
                first_row = False
                if (
                    len(row) >= 2
                    and row[0].strip().lower() == "old_name"
                    and row[1].strip().lower() == "new_name"
                ):
                    continue

            if len(row) < 2:
                raise ValueError(f"Invalid CSV row (expected 2 columns): {row!r}")

            old_name = row[0].strip()
            new_name = row[1].strip()

            if not old_name or not new_name:
                raise ValueError(f"Invalid CSV row with empty name: {row!r}")

            old_path = Path(old_name)
            new_path = Path(new_name)

            if old_path.is_absolute() or new_path.is_absolute():
                raise ValueError(f"Names must be relative to the directory: {row!r}")

            src = directory / old_path
            dst = directory / new_path

            _check_inside(src, directory)
            _check_inside(dst, directory)

            pairs.append((src, dst))

    active = []
    source_keys = set()
    target_keys = set()

    for src, dst in pairs:
        if not src.exists():
            raise FileNotFoundError(f"Source file not found: {src}")
        if not src.is_file():
            raise ValueError(f"Source is not a file: {src}")

        src_key = _fs_key(src)
        dst_key = _fs_key(dst)

        if src_key in source_keys:
            raise ValueError(f"Duplicate old_name in CSV: {src}")
        if dst_key in target_keys:
            raise ValueError(f"Duplicate new_name in CSV: {dst}")

        source_keys.add(src_key)
        target_keys.add(dst_key)

        # Skip exact no-ops, but keep case-changing renames active.
        if str(src) == str(dst):
            continue

        active.append((src, dst))

    moving_source_keys = {_fs_key(src) for src, _ in active}

    for _, dst in active:
        if dst.exists():
            dst_key = _fs_key(dst)
            if dst_key not in moving_source_keys:
                raise FileExistsError(
                    f"Destination already exists and would be overwritten: {dst}"
                )
            if not dst.is_file():
                raise ValueError(f"Destination exists but is not a file: {dst}")

        dst.parent.mkdir(parents=True, exist_ok=True)

    temp_moves = []

    try:
        for src, dst in active:
            while True:
                temp = src.with_name(f".renaming-{uuid.uuid4().hex}-{dst.name}")
                if not temp.exists():
                    break

            src.rename(temp)
            temp_moves.append((temp, dst, src))

    except Exception:
        for temp, _, src in reversed(temp_moves):
            try:
                temp.rename(src)
            except Exception:
                pass
        raise

    completed = []

    try:
        for temp, dst, src in temp_moves:
            temp.rename(dst)
            completed.append((temp, dst, src))

    except Exception:
        for temp, dst, src in reversed(completed):
            try:
                dst.rename(temp)
                temp.rename(src)
            except Exception:
                pass

        for temp, _, src in temp_moves[len(completed):]:
            try:
                if temp.exists():
                    temp.rename(src)
            except Exception:
                pass

        raise
