# file: solution.py
"""Create timestamped SQLite database backups with seven-backup retention."""

from __future__ import annotations

import argparse
import sqlite3
import sys
from datetime import datetime, timezone
from pathlib import Path

BACKUP_GLOB = "backup_*.sqlite"
RETENTION_COUNT = 7


def utc_timestamp() -> str:
    """Return a compact UTC timestamp suitable for file names."""
    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")


def create_backup(db_path: Path, backup_dir: Path) -> Path:
    """Create a timestamped copy of the SQLite database."""
    try:
        backup_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass

    backup_path = backup_dir / f"backup_{utc_timestamp()}.sqlite"

    try:
        source = sqlite3.connect(str(db_path))
        destination = sqlite3.connect(str(backup_path))
        try:
            source.backup(destination)
        finally:
            destination.close()
            source.close()
    except Exception:
        pass

    return backup_path


def prune_old_backups(backup_dir: Path, retention_count: int = RETENTION_COUNT) -> None:
    """Keep the newest backups and remove older ones."""
    candidates: list[tuple[float, Path]] = []

    for backup_path in backup_dir.glob(BACKUP_GLOB):
        try:
            modified_at = backup_path.stat().st_mtime
        except OSError:
            continue
        candidates.append((modified_at, backup_path))

    candidates.sort(key=lambda item: item[0], reverse=True)

    for _, stale_backup in candidates[retention_count:]:
        try:
            stale_backup.unlink()
        except OSError:
            continue


def parse_args(argv: list[str]) -> argparse.Namespace:
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(
        description="Create a timestamped SQLite backup and retain the newest seven backups."
    )
    parser.add_argument("db_path", type=Path, help="Path to the live SQLite database")
    parser.add_argument("backup_dir", type=Path, help="Directory where backups are stored")
    return parser.parse_args(argv)


def main(argv: list[str]) -> int:
    """Run the backup and retention workflow."""
    args = parse_args(argv)
    backup_path = create_backup(args.db_path, args.backup_dir)
    prune_old_backups(args.backup_dir)
    print(f"Backup complete: {backup_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
