import time


def wait_for_export(client_base, job_id):
    poll_interval_seconds = 2
    max_wait_seconds = 10 * 60
    deadline = time.monotonic() + max_wait_seconds
    max_attempts = int(max_wait_seconds // poll_interval_seconds)

    def _get_field(payload, field):
        get_method = getattr(payload, "get", None)
        if callable(get_method):
            return get_method(field)
        return getattr(payload, field, None)

    for _ in range(max_attempts):
        if time.monotonic() >= deadline:
            break

        response = client_base.get(f"/exports/{job_id}")

        if callable(getattr(response, "raise_for_status", None)):
            response.raise_for_status()

        if callable(getattr(response, "json", None)):
            payload = response.json()
        else:
            payload = response

        if _get_field(payload, "status") == "complete":
            return _get_field(payload, "download_url")

        remaining = deadline - time.monotonic()
        if remaining <= 0:
            break

        time.sleep(min(poll_interval_seconds, remaining))

    raise TimeoutError(
        f"Export job '{job_id}' did not complete within {max_wait_seconds} seconds"
