Here is a robust implementation that writes each chunk to a temporary file, renames it into place, and atomically writes `manifest.json` only after all parts are complete.

```python
# file: solution.py
import csv
import json
import os
from collections.abc import Mapping


def _fsync_dir(path):
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError:
        return

    try:
        os.fsync(fd)
    except OSError:
        pass
    finally:
        os.close(fd)


def _as_csv_row(row):
    """
    Normalize a row for csv.writer.

    - Mappings are left alone for DictWriter.
    - Strings/bytes are treated as a single-field row.
    - Non-iterable scalars are wrapped in a list.
    """
    if isinstance(row, Mapping):
        return row

    if isinstance(row, (str, bytes, bytearray)):
        return [row]

    try:
        iter(row)
    except TypeError:
        return [row]

    return row


def _write_manifest(out_dir, parts):
    manifest_path = os.path.join(out_dir, "manifest.json")
    tmp_path = manifest_path + ".tmp"

    manifest = {
        "parts": parts,
    }

    try:
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(manifest, f, indent=2)
            f.write("\n")
            f.flush()
            os.fsync(f.fileno())

        os.replace(tmp_path, manifest_path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

    _fsync_dir(out_dir)


def export_parts(rows, out_dir, chunk_size=10000):
    """
    Write rows into numbered CSV part files and finish with manifest.json.

    Manifest schema:
    {
        "parts": [
            {"file": "part-00000.csv", "row_count": 10000},
            {"file": "part-00001.csv", "row_count": 42}
        ]
    }
    """
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")

    os.makedirs(out_dir, exist_ok=True)

    row_iter = iter(rows)

    try:
        current_row = _as_csv_row(next(row_iter))
    except StopIteration:
        parts = []
        _write_manifest(out_dir, parts)
        return parts

    if isinstance(current_row, Mapping):
        fieldnames = list(current_row.keys())
    else:
        fieldnames = None

    parts = []
    part_index = 0

    while True:
        part_name = f"part-{part_index:05d}.csv"
        final_path = os.path.join(out_dir, part_name)
        tmp_path = final_path + ".tmp"
        row_count = 0

        try:
            with open(tmp_path, "w", newline="", encoding="utf-8") as f:
                if fieldnames is not None:
                    writer = csv.DictWriter(
                        f,
                        fieldnames=fieldnames,
                        restval="",
                        extrasaction="ignore",
                    )
                    writer.writeheader()

                    while True:
                        writer.writerow(dict(current_row))
                        row_count += 1

                        if row_count >= chunk_size:
                            break

                        try:
                            current_row = _as_csv_row(next(row_iter))
                        except StopIteration:
                            break
                else:
                    writer = csv.writer(f)

                    while True:
                        writer.writerow(current_row)
                        row_count += 1

                        if row_count >= chunk_size:
                            break

                        try:
                            current_row = _as_csv_row(next(row_iter))
                        except StopIteration:
                            break

                f.flush()
                os.fsync(f.fileno())

            os.replace(tmp_path, final_path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

        parts.append({"file": part_name, "row_count": row_count})
        part_index += 1

        if row_count < chunk_size:
            break

        try:
            current_row = _as_csv_row(next(row_iter))
        except StopIteration:
            break

    _fsync_dir(out_dir)
    _write_manifest(out_dir, parts)
    return parts
